#!/usr/bin/env bash
# KOKPIT2_PREVIEW — Yeni kokpit'i ONIZLEME olarak yayinla. CANLIYA (/api/bi/kokpit) DOKUNMAZ.
#   1) bi_tahsilat portfoy endpoint'i (kalici)  2) /api/bi/kokpit2 onizleme route'u  3) shells/kokpit2.html
#   Eski kokpit aynen calisir. Onayladiktan sonra CUTOVER ayri adim.
set -e
cd /opt/krb-assessment
SRV=server_container.mjs
[ -f "$SRV" ] || { echo "HATA: $SRV yok (dizin yanlis olabilir)"; exit 1; }

TS=$(date +%s)
cp "$SRV" "$SRV.bak.$TS"
echo "yedek: $SRV.bak.$TS"

# --- patch dosyalarini yaz ---
printf '%s' '' | base64 -d > /tmp/patch_tahsilat_ozet.py
printf '%s' '' | base64 -d > /tmp/patch_kokpit2_route.py

# --- endpoint (kalici) + onizleme route (gecici) ---
python3 /tmp/patch_tahsilat_ozet.py "$SRV"
python3 /tmp/patch_kokpit2_route.py "$SRV"

# --- server syntax dogrula (basarisizsa geri al) ---
if ! node --check "$SRV"; then
  echo "!! node --check BASARISIZ — geri aliniyor"; cp "$SRV.bak.$TS" "$SRV"; exit 1
fi
echo "node --check: OK"

# --- yeni kokpit HTML'i shells/kokpit2.html'e yaz ---
printf '%s' '' | base64 -d > shells/kokpit2.html
echo "shells/kokpit2.html satir: $(wc -l < shells/kokpit2.html)"

# --- build + restart ---
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4

# --- dogrulama ---
echo "== route'lar =="
docker exec krb-assessment sh -c "grep -c 'tahsilat-ozet' /app/server_container.mjs && grep -c '/api/bi/kokpit2' /app/server_container.mjs" || true
echo "== kokpit2.html container icinde =="
docker exec krb-assessment sh -c "wc -l < /app/shells/kokpit2.html" || true
echo ""
echo "== ONIZLE: tarayicida  /api/bi/kokpit2  ac  (eski: /api/bi/kokpit) =="
echo "== DONE =="
